18	    public void handle(@Parameter MethodArgumentNotValidException ex,
19	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
20	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
21	                "The request contains invalid or missing parameters");
22	        BindingResult bindingResult = ex.getBindingResult();
23	        if (bindingResult.hasErrors()) {
24	            List<String> errors = bindingResult.getFieldErrors().stream()
25	                    .map(FieldError::getField)
26	                    .distinct()
27	                    .toList();
28	            detail.setProperty("errors", errors);
29	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
30	                    .map(fieldError -> {
31	                        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
32	                        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
33	                        String message = "Field '%s' %s (rejected value: %s)".formatted(
34	                                fieldError.getField(), defaultMessage, rejectedValue);
35	                        return new ValidationMessageDto(message)
36	                                .putAdditionalProperty("field", fieldError.getField())
37	                                .putAdditionalProperty("rejectedValue", rejectedValue)
38	                                .putAdditionalProperty("defaultMessage", defaultMessage);
39	                    })
40	                    .toList();
41	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
42	        }
43	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
44	    }
45	}
